function money(amount: string | number, currency: string) {
  return new Intl.NumberFormat(undefined, { style: "currency", currency, maximumFractionDigits: 2 }).format(Number(amount));
}
function label(value: string) { return value.replaceAll("_", " "); }
function statusClass(value: string) { return `admin-status ${value === "operational" || value === "ready" || value === "active" ? "good" : value === "error" || value === "attention" || value === "failed" ? "danger" : "muted"}`; }
function EmptyPanel({ title, detail }: { title: string; detail: string }) { return <div className="admin-empty"><FileText size={22} /><h3>{title}</h3><p>{detail}</p></div>; }
function csvValue(value: unknown) { const text = value === null || value === undefined ? "" : String(value); return `"${text.replaceAll('"', '""')}"`; }
function downloadCsv(filename: string, headers: string[], rows: Array<Array<unknown>>) { const csv = [headers, ...rows].map((row) => row.map(csvValue).join(",")).join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = filename; anchor.click(); URL.revokeObjectURL(url); }

function AdminAccessGate() {
  const { user, loading, logout } = useAuth();
  const [, setLocation] = useLocation();
  const adminAccess = trpc.auth.adminAccess.useQuery(undefined, { enabled: Boolean(user) });
  if (loading) return <main className="admin-access-page"><div className="admin-access-mark">V</div><p>Validating secure administrator access…</p></main>;
  if (!user) return <main className="admin-access-page"><div className="admin-access-mark">V</div><span>VAMNUX / SUPER ADMIN</span><h1>Secure operations<br /><em>only.</em></h1><p>Sign in through the configured secure identity flow. Admin authorization is verified on every protected request.</p><button type="button" onClick={() => startLogin()} className="admin-primary-action">Secure sign in <ArrowRight size={15} /></button></main>;
  if (adminAccess.isLoading) return <main className="admin-access-page"><div className="admin-access-mark">V</div><p>Validating server-side owner access…</p></main>;
  if (!adminAccess.data?.allowed) return <main className="admin-access-page"><div className="admin-access-mark danger"><ShieldAlert size={21} /></div><span>VAMNUX / ACCESS RESTRICTED</span><h1>Administrator<br /><em>approval required.</em></h1><p>Your current account is not the approved VAMNUX owner account. No operational data or privileged controls have been loaded.</p><button type="button" onClick={logout} className="admin-secondary-action">Sign out</button><Link href="/" className="admin-return-link">Return to marketplace</Link></main>;
  return <SuperAdminWorkspace adminName={user.name || "VAMNUX owner"} onSignOut={logout} onReturn={() => setLocation("/")} />;
}

