  const refreshAdminData = async () => {
    await Promise.all([utils.admin.getOverview.invalidate(), utils.admin.listAuditEvents.invalidate(), utils.admin.listCustomers.invalidate(), utils.admin.listWalletFundingRequests.invalidate(), utils.admin.listSupportTickets.invalidate(), utils.admin.getMarketplacePricingSettings.invalidate(), utils.admin.listCatalogPricing.invalidate(), utils.admin.listPriceChangeHistory.invalidate(), utils.admin.listAdminProductOperations.invalidate(), utils.admin.listAdminManagedCatalog.invalidate(), utils.admin.listAuthorizedCatalogSources.invalidate(), utils.admin.listMarketplaceCategories.invalidate(), utils.admin.listExchangeRates.invalidate(), utils.admin.listSiteContentBlocks.invalidate(), utils.admin.listSupplierSyncRuns.invalidate(), utils.admin.getFinanceAnalytics.invalidate(), utils.admin.listPromotions.invalidate(), utils.admin.getReferralSettings.invalidate(), utils.admin.getLoyaltySettings.invalidate(), utils.admin.listResellers.invalidate(), utils.admin.listSiteSettings.invalidate(), utils.admin.listNotificationTemplates.invalidate(), utils.admin.listApiRequestLogs.invalidate(), utils.admin.listSupplierWebhookEvents.invalidate(), utils.marketplace.catalog.invalidate()]); 
  };
  const updateDefaultMarkup = trpc.admin.updateMarketplacePricingSettings.useMutation({ onSuccess: async () => { toast.success("Global VAMNUX markup updated and audit logged."); await refreshAdminData(); }, onError: (error) => toast.error(error.message || "Could not update global markup.") });
