  const createMarketplaceCategory = trpc.admin.createMarketplaceCategory.useMutation({ onSuccess: async () => { toast.success("Category created and audit logged."); setCategoryDraft({ slug: "", name: "", description: "", imageUrl: "", seoTitle: "", seoDescription: "", sortOrder: "0", visible: true, featured: false, status: "active" }); setIsCategoryEditorOpen(false); await refreshAdminData(); }, onError: (error) => toast.error(error.message || "Could not create the category.") });
  const updateMarketplaceCategory = trpc.admin.updateMarketplaceCategory.useMutation({ onSuccess: async () => { toast.success("Category updated and audit logged."); setEditingCategoryId(null); setIsCategoryEditorOpen(false); setCategoryDraft({ slug: "", name: "", description: "", imageUrl: "", seoTitle: "", seoDescription: "", sortOrder: "0", visible: true, featured: false, status: "active" }); await refreshAdminData(); }, onError: (error) => toast.error(error.message || "Could not update the category.") });
