  const createManualProduct = trpc.admin.createAdminManagedCatalogProduct.useMutation({ onSuccess: async (product) => { toast.success(`${product.name} saved as ${product.status}.`); setManualProductDraft((draft) => ({ name: "", category: "gift_card", description: "", catalogSourceId: draft.catalogSourceId, basePrice: "", regionLabel: "", deliveryEstimate: "", deliveryMinMinutes: "", deliveryMaxMinutes: "", customerRequirements: "", deliveryType: "digital_code", recipientEmailRequired: false, status: "draft" })); await refreshAdminData(); }, onError: (error) => toast.error(error.message || "Could not create manual product.") });
  const updateManualProduct = trpc.admin.updateAdminManagedCatalogProduct.useMutation({ onSuccess: async (product) => { toast.success(`${product.name} updated and audit logged.`); setEditingManualProductId(null); await refreshAdminData(); }, onError: (error) => toast.error(error.message || "Could not update manual product.") });
  const updateManualProductStatus = trpc.admin.setAdminManagedCatalogProductStatus.useMutation({ onSuccess: async (product) => { toast.success(`${product.name} is now ${product.status}.`); await refreshAdminData(); }, onError: (error) => toast.error(error.message || "Could not update manual product status.") });
  const suspendCustomer = trpc.admin.suspendCustomer.useMutation({ onSuccess: async (result) => { toast.success(result.suspendedUntil ? "Customer suspended until the recorded expiry." : "Customer suspended until reinstated."); await refreshAdminData(); }, onError: (error) => toast.error(error.message || "Could not suspend customer.") });
  const reinstateCustomer = trpc.admin.reinstateCustomer.useMutation({ onSuccess: async () => { toast.success("Customer account reinstated and audit logged."); await refreshAdminData(); }, onError: (error) => toast.error(error.message || "Could not reinstate customer.") });
  const upsertRate = trpc.admin.upsertExchangeRate.useMutation({ onSuccess: async () => { toast.success("Manual exchange rate saved and audit logged. Storefront conversion remains a separate controlled policy."); setRateDraft({ baseCurrency: "USD", quoteCurrency: "NGN", rate: "", bufferPercent: "0", active: true }); await refreshAdminData(); }, onError: (error) => toast.error(error.message || "Could not save the exchange rate.") });
