    const reset = () => { setEditingManualProductId(null); setManualProductDraft({ name: "", category: "gift_card", description: "", catalogSourceId: "", basePrice: "", regionLabel: "", deliveryEstimate: "", deliveryMinMinutes: "", deliveryMaxMinutes: "", customerRequirements: "", deliveryType: "digital_code", recipientEmailRequired: false, status: "draft" }); };
