    return <section className="admin-panel admin-manual-products"><header><div><span>MANUAL PRODUCT LISTINGS</span><h2>Create controlled catalog items</h2><p>Only active authorized sources may be used. Delivery ranges and purchase requirements are customer-facing guidance, not unsupported fulfilment guarantees.</p></div><PackageSearch size={21} /></header><div className="admin-pricing-grid"><form onSubmit={submitManualProduct}><p className="admin-form-kicker">{editingManualProductId ? "EDIT MANUAL PRODUCT" : "ADD MANUAL PRODUCT"}</p><label>Product name<input required value={manualProductDraft.name} maxLength={255} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, name: event.target.value }))} /></label><div className="admin-form-split"><label>Category<select value={manualProductDraft.category} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, category: event.target.value as ManualProductDraft["category"] }))}><option value="gift_card">Gift card</option><option value="subscription">Subscription</option><option value="software">Software</option><option value="ai_tool">AI tool</option><option value="game_key">Game key</option><option value="steam">Steam</option><option value="telegram_stars">Telegram Stars</option></select></label><label>Authorized source<select required value={manualProductDraft.catalogSourceId} disabled={Boolean(editingManualProductId)} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, catalogSourceId: event.target.value }))}><option value="">Select an active source</option>{activeSources.map((source) => <option key={source.id} value={source.id}>{source.displayName}</option>)}</select></label></div><label>Customer description<textarea required value={manualProductDraft.description} maxLength={2000} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, description: event.target.value }))} /></label><div className="admin-form-split"><label>USD base price<input required inputMode="decimal" value={manualProductDraft.basePrice} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, basePrice: event.target.value }))} placeholder="0.00" /></label><label>Region <small>optional</small><input value={manualProductDraft.regionLabel} maxLength={120} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, regionLabel: event.target.value }))} placeholder="Global / country" /></label></div><label>Delivery terms<input required value={manualProductDraft.deliveryEstimate} maxLength={160} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, deliveryEstimate: event.target.value }))} placeholder="Example: Usually within one business day after requirements are verified" /></label><div className="admin-form-split"><label>Minimum delivery <small>minutes, optional</small><input inputMode="numeric" value={manualProductDraft.deliveryMinMinutes ?? ""} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, deliveryMinMinutes: event.target.value }))} placeholder="0" /></label><label>Maximum delivery <small>minutes, optional</small><input inputMode="numeric" value={manualProductDraft.deliveryMaxMinutes ?? ""} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, deliveryMaxMinutes: event.target.value }))} placeholder="1440" /></label></div><label>Customer requirements <small>optional</small><textarea value={manualProductDraft.customerRequirements ?? ""} maxLength={2000} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, customerRequirements: event.target.value }))} placeholder="Explain any player ID, account email, server, region, or verification information needed before delivery." /></label><div className="admin-form-split"><label>Delivery format<select value={manualProductDraft.deliveryType} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, deliveryType: event.target.value as ManualProductDraft["deliveryType"] }))}><option value="digital_code">Digital code</option><option value="activation_link">Activation link</option><option value="manual_processing">Manual processing</option><option value="account_access">Account access</option></select></label><label>Status<select value={manualProductDraft.status} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, status: event.target.value as ManualProductDraft["status"] }))}><option value="draft">Draft</option><option value="active">Live</option><option value="paused">Disabled / paused</option>{editingManualProductId && <option value="archived">Archived (safe delete)</option>}</select></label></div><label className="admin-check"><input type="checkbox" checked={manualProductDraft.recipientEmailRequired} onChange={(event) => setManualProductDraft((draft) => ({ ...draft, recipientEmailRequired: event.target.checked }))} /> Require recipient email for an order draft</label><div className="admin-funding-actions"><button type="submit" disabled={isSaving || (!editingManualProductId && !activeSources.length)} className="admin-primary-action">{isSaving ? "Saving…" : editingManualProductId ? "Save changes" : "Add manual product"}</button>{editingManualProductId && <button type="button" className="admin-secondary-action" onClick={reset}>Cancel edit</button>}</div></form><div className="admin-table-wrap"><table><thead><tr><th>Product</th><th>Source</th><th>Delivery</th><th>Requirements</th><th>Status</th><th /></tr></thead><tbody>{!(adminManagedCatalog.data ?? []).length ? <tr><td colSpan={6}>No manual listings yet. Supplier-synchronised products remain in the protected catalog controls above.</td></tr> : adminManagedCatalog.data.map((product) => <tr key={product.id}><td><strong>{product.name}</strong><small>{label(product.category)} · {money(product.basePrice, product.baseCurrency)}</small></td><td>{product.sourceName}<small>{label(product.sourceType)}</small></td><td>{product.deliveryEstimate || "No estimate"}<small>{product.deliveryMinMinutes !== null && product.deliveryMaxMinutes !== null ? `${product.deliveryMinMinutes}–${product.deliveryMaxMinutes} minutes` : label(product.deliveryType)}</small></td><td><small>{product.customerRequirements || "No additional requirements recorded"}</small></td><td><span className={statusClass(product.status)}>{product.status}</span></td><td><div className="admin-funding-actions"><button type="button" className="admin-secondary-action" onClick={() => edit(product)}>Edit</button>{product.status !== "paused" && <button type="button" className="admin-secondary-action" onClick={() => { if (window.confirm(`Disable ${product.name}? It will no longer be active in the VAMNUX catalog.`)) updateManualProductStatus.mutate({ productId: product.id, status: "paused" }); }}>Disable</button>}{product.status !== "archived" && <button type="button" className="admin-danger-action" onClick={() => { if (window.confirm(`Archive ${product.name}? This preserves history and removes it from active catalog use.`)) updateManualProductStatus.mutate({ productId: product.id, status: "archived" }); }}>Archive</button>}</div></td></tr>)}</tbody></table></div></div></section>;
